content.css:
.selection-waterfall-root {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
}
.selection-waterfall-root svg {
  shape-rendering: geometricPrecision;
}
/* ── KPI Strip ── */
.sw-kpi-strip {
  display: flex;
  gap: 0;
  padding: 6px 12px;
  border-bottom: 1px solid #e8e8e8;
  background: #fafbfc;
  flex-shrink: 0;
}
.sw-kpi-item {
  flex: 1;
  text-align: center;
  border-right: 1px solid #e0e0e0;
  padding: 2px 8px;
}
.sw-kpi-item:last-child {
  border-right: none;
}
.sw-kpi-value {
  font-size: 16px;
  font-weight: 700;
  color: #2c3e50;
  line-height: 1.2;
}
.sw-kpi-label {
  font-size: 9px;
  color: #8899aa;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-top: 1px;
}
.sw-kpi-value--selected {
  color: #27ae60;
}
.sw-kpi-value--deferred {
  color: #95a5a6;
}
.sw-kpi-value--remaining {
  color: #2980b9;
}
/* ── Axes ── */
.sw-axis .tick line {
  stroke: #d0d0d0;
  stroke-width: 0.5;
}
.sw-axis .tick text {
  fill: #666;
  font-size: 11px;
}
.sw-axis .domain {
  stroke: #aaa;
  stroke-width: 1;
}
.sw-axis-label {
  fill: #444;
  font-size: 12px;
  font-weight: 600;
}
/* ── Bars ── */
.sw-bar {
  cursor: pointer;
  stroke: #fff;
  stroke-width: 1;
  transition: opacity 0.15s ease;
}
.sw-bar:hover {
  filter: brightness(1.12);
  stroke-width: 1.5;
}
.sw-bar.dimmed {
  opacity: 0.25;
}
/* ── Data labels ── */
.sw-data-label {
  font-size: 9px;
  fill: #555;
  pointer-events: none;
  text-anchor: middle;
}
/* ── Cut line ── */
.sw-cut-line {
  stroke-dasharray: 6 3;
}
.sw-cut-label {
  font-size: 10px;
  font-weight: 600;
}
/* ── Cumulative line ── */
.sw-cumulative-line {
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.sw-cumulative-dot {
  stroke: #fff;
  stroke-width: 1.5;
}
/* ── Grid ── */
.sw-grid-line {
  stroke: #e8e8e8;
  stroke-width: 0.5;
  stroke-dasharray: 3 3;
}
/* ── Legend ── */
.sw-legend {
  font-size: 11px;
  fill: #555;
}
.sw-legend-swatch {
  stroke: #fff;
  stroke-width: 0.5;
}
/* ── Landing page ── */
.sw-landing {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: #888;
  font-size: 14px;
  text-align: center;
  padding: 24px;
  box-sizing: border-box;
}
.sw-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: #94a3b8;
  font-size: 12px;
  text-align: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
  letter-spacing: 0.2px;
}
/* ── Insight Panel ── */
.sw-insight-panel {
  display: none;
  flex-direction: column;
  width: 220px;
  min-width: 220px;
  padding: 12px;
  border-left: 1px solid #e0e0e0;
  background: #fafafa;
  overflow-y: auto;
  font-size: 11px;
  gap: 4px;
}
.sw-insight-title {
  font-weight: 700;
  font-size: 13px;
  color: #333;
  margin-bottom: 8px;
  padding-bottom: 6px;
  border-bottom: 2px solid #E8612A;
}
.sw-insight-row {
  display: flex;
  justify-content: space-between;
  padding: 3px 0;
}
.sw-insight-label {
  color: #666;
}
.sw-insight-value {
  font-weight: 600;
  color: #333;
}
.sw-insight--selected .sw-insight-value {
  color: #27ae60;
}
.sw-insight--deferred .sw-insight-value {
  color: #95a5a6;
}
.sw-insight-bar-wrap {
  margin-top: 12px;
  padding-top: 8px;
  border-top: 1px solid #e0e0e0;
}
.sw-insight-bar-label {
  font-weight: 600;
  margin-bottom: 4px;
  color: #333;
}
.sw-insight-bar-track {
  height: 16px;
  background: #e0e0e0;
  border-radius: 8px;
  overflow: hidden;
}
.sw-insight-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #27ae60, #2ecc71);
  border-radius: 8px;
  transition: width 0.3s ease;
}
.sw-insight-bar-pct {
  font-size: 10px;
  color: #888;
  margin-top: 2px;
  text-align: right;
}
.sw-insight-opportunity {
  margin-top: 12px;
  padding: 8px;
  background: #fff3e0;
  border-radius: 6px;
  border-left: 3px solid #E8612A;
}
.sw-insight-opp-title {
  font-weight: 600;
  font-size: 10px;
  color: #E8612A;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 4px;
}
.sw-insight-opp-name {
  font-weight: 600;
  color: #333;
}
.sw-insight-opp-detail {
  font-size: 10px;
  color: #666;
  margin-top: 2px;
}
/* ── Main Area Wrapper ── */
.sw-main-area {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
  overflow: hidden;
}
/* ── License Badge & Watermark ── */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: rgba(5, 150, 105, 0.08);
  border: 1px solid rgba(5, 150, 105, 0.25);
  color: #059669;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
.bfusion-watermark {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 15;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  background: repeating-linear-gradient(-45deg, transparent, transparent 120px, rgba(220, 38, 38, 0.03) 120px, rgba(220, 38, 38, 0.03) 122px);
}
.bfusion-watermark__content {
  text-align: center;
  opacity: 0.18;
  user-select: none;
  transform: rotate(-18deg);
}
.bfusion-watermark__title {
  font-size: 56px;
  font-weight: 900;
  color: #DC2626;
  letter-spacing: 12px;
  line-height: 1;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__subtitle {
  font-size: 16px;
  font-weight: 600;
  color: #DC2626;
  margin-top: 6px;
  letter-spacing: 3px;
  text-transform: uppercase;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__link {
  font-size: 11px;
  color: #9CA3AF;
  margin-top: 12px;
  font-family: "Segoe UI", sans-serif;
}
